openai_client.py — Minimal stdlib-only client for OpenAI Responses API.

Features
- Non-streaming text responses via POST /v1/responses
- Optional streaming via Server-Sent Events (SSE)
- No third-party dependencies; uses urllib from the Python standard library
- API key read from "'`OPENAI_API_KEY` or passed explicitly
- Small CLI: echo "prompt" | python -m openai_client --model gpt-4.1-mini

Notes
- This client avoids logging prompts/keys and uses HTTPS.
- It targets the Responses API (preferred) and tries to be resilient to
  schema variations by extracting `output_text` when present, or falling back
  to parsing `output` or legacy `choices` structures.
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Dict, Generator, Iterable, Optional


DEFAULT_BASE_URL = "https://api.openai.com/v1"
RESPONSES_PATH = "/responses"
ENV_API_KEY = "OPENAI_API_KEY"


class OpenAIAPIError(Exception):
    def __init__(self, status: int, message: str, *, payload: Optional[dict] = None):
        super().__init__(f"HTTP {status}: {message}")
        self.status = status
        self.message = message
        self.payload = payload or {}


class OpenAIClient:
    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: str = DEFAULT_BASE_URL,
        organization: Optional[str] = None,
        project: Optional[str] = None,
        timeout: float = 30.0,
        default_model: str = "gpt-4.1-mini",
    ) -> None:
        self.api_key = api_key or os.getenv(ENV_API_KEY) or ""
        if not self.api_key:
            raise ValueError(
                f"Missing API key. Set {ENV_API_KEY} or pass api_key explicitly."
            )
        self.base_url = base_url.rstrip("/")
        self.organization = organization or os.getenv("OPENAI_ORG")
        self.project = project or os.getenv("OPENAI_PROJECT")
        self.timeout = timeout
        self.default_model = default_model

    # Public API
    def respond(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        system: Optional[str] = None,
        temperature: Optional[float] = None,
        top_p: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra: Optional[Dict] = None,
    ) -> Dict:
        """Send a non-streaming Responses API call and return the JSON dict."""
        body: Dict[str, object] = {
            "model": model or self.default_model,
            "input": prompt,
        }
        if system is not None:
            body["system"] = system
        if temperature is not None:
            body["temperature"] = float(temperature)
        if top_p is not None:
            body["top_p"] = float(top_p)
        if max_output_tokens is not None:
            body["max_output_tokens"] = int(max_output_tokens)
        if extra:
            # last-wins merge for any advanced fields the caller wants to set
            body.update(extra)

        return self._json_request(RESPONSES_PATH, body, stream=False)

    def complete(
        self,
        prompt: str,
        **kwargs,
    ) -> str:
        """Send a prompt and return extracted plain text.

        Accepts same kwargs as `respond()`.
        """
        data = self.respond(prompt, **kwargs)
        return extract_text(data)

    def stream(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        system: Optional[str] = None,
        temperature: Optional[float] = None,
        top_p: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra: Optional[Dict] = None,
    ) -> Iterable[str]:
        """Yield streaming text deltas as they arrive from the API (SSE)."""
        body: Dict[str, object] = {
            "model": model or self.default_model,
            "input": prompt,
            "stream": True,
        }
        if system is not None:
            body["system"] = system
        if temperature is not None:
            body["temperature"] = float(temperature)
        if top_p is not None:
            body["top_p"] = float(top_p)
        if max_output_tokens is not None:
            body["max_output_tokens"] = int(max_output_tokens)
        if extra:
            body.update(extra)

        return self._sse_request(RESPONSES_PATH, body)

    # Low-level HTTP helpers
    def _build_headers(self, *, sse: bool = False) -> Dict[str, str]:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "User-Agent": "openai-client-stdlib/1.0",
        }
        if sse:
            headers["Accept"] = "text/event-stream"
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        return headers

    def _json_request(self, path: str, body: Dict, *, stream: bool) -> Dict:
        url = f"{self.base_url}{path}"
        data = json.dumps(body).encode("utf-8")
        req = urllib.request.Request(url, data=data, method="POST")
        for k, v in self._build_headers(sse=stream).items():
            req.add_header(k, v)

        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                charset = resp.headers.get_content_charset() or "utf-8"
                raw = resp.read().decode(charset, errors="replace")
                return json.loads(raw)
        except urllib.error.HTTPError as e:
            message, payload = _read_http_error(e)
            raise OpenAIAPIError(e.code, message, payload=payload)
        except urllib.error.URLError as e:
            raise OpenAIAPIError(0, f"Network error: {e.reason}")

    def _sse_request(self, path: str, body: Dict) -> Iterable[str]:
        url = f"{self.base_url}{path}"
        data = json.dumps(body).encode("utf-8")
        req = urllib.request.Request(url, data=data, method="POST")
        for k, v in self._build_headers(sse=True).items():
            req.add_header(k, v)

        try:
            resp = urllib.request.urlopen(req, timeout=self.timeout)
        except urllib.error.HTTPError as e:
            message, payload = _read_http_error(e)
            raise OpenAIAPIError(e.code, message, payload=payload)
        except urllib.error.URLError as e:
            raise OpenAIAPIError(0, f"Network error: {e.reason}")

        # Return a generator that yields deltas and ensures cleanup
        def _gen() -> Generator[str, None, None]:
            try:
                while True:
                    line = resp.readline()
                    if not line:
                        break
                    try:
                        text = line.decode("utf-8", errors="ignore").rstrip("'"\\r\\n\")
                    except Exception:
                        continue
                    if not text:
                        continue
                    # SSE format: lines beginning with \"data: \" contain the payload
                    if not text.startswith(\"data:\"):
                        continue
                    payload = text[5:].strip()
                    if not payload or payload == \"[DONE]\":
                        # Some implementations send [DONE] at the end
                        if payload == \"[DONE]\":
                            break
                        continue
                    try:
                        evt = json.loads(payload)
                    except json.JSONDecodeError:
                        # If the server ever sends raw deltas as plain strings
                        yield payload
                        continue

                    # Common Responses SSE shapes
                    etype = evt.get(\"type\")
                    if etype in {\"response.output_text.delta\", \"content.delta\"}:
                        delta = evt.get(\"delta\")
                        if isinstance(delta, str):
                            yield delta
                        continue
                    if etype in {\"response.completed\", \"response.stop\"}:
                        break
                    if etype == \"response.error\":
                        err = evt.get(\"error\") or {}
                        msg = err.get(\"message\") or \"Streaming error\"
                        code = err.get(\"code\") or \"\"
                        raise OpenAIAPIError(0, f\"{msg} ({code})\", payload=evt)

                    # Fallbacks: sometimes a whole chunk of text may appear under these keys
                    if \"output_text\" in evt and isinstance(evt[\"output_text\"], str):
                        yield evt[\"output_text\"]
                        continue
                    if \"delta\" in evt and isinstance(evt[\"delta\"], str):
                        yield evt[\"delta\"]
                        continue
            finally:
                try:
                    resp.close()
                except Exception:
                    pass

        return _gen()


def extract_text(resp: Dict) -> str:
    \"\"\"Best-effort extraction of assistant text from a Responses API result.

    Priority:
    1) resp[\"output_text\"] if present
    2) Aggregate text from resp[\"output\"][...]
    3) Legacy compat: resp[\"choices\"][0][\"message\"][\"content\"] or [\"text\"]
    \"\"\"
    # 1) Direct convenience field
    out = resp.get(\"output_text\")
    if isinstance(out, str) and out.strip():
        return out

    # 2) Walk the output array
    output = resp.get(\"output\")
    if isinstance(output, list):
        parts: list[str] = []
        for item in output:
            if not isinstance(item, dict):
                continue
            itype = item.get(\"type\")
            if itype == \"output_text\":
                txt = item.get(\"text\")
                if isinstance(txt, str):
                    parts.append(txt)
            elif itype == \"message\":
                content = item.get(\"content\")
                if isinstance(content, list):
                    for c in content:
                        if not isinstance(c, dict):
                            continue
                        if c.get(\"type\") in {\"output_text\", \"input_text\", \"text\"}:
                            t = c.get(\"text\")
                            if isinstance(t, str):
                                parts.append(t)
        if parts:
            return \"\".join(parts)

    # 3) Legacy/compat fallbacks (chat/completions-like)
    choices = resp.get(\"choices\")
    if isinstance(choices, list) and choices:
        first = choices[0] or {}
        msg = first.get(\"message\") or {}
        content = msg.get(\"content\")
        if isinstance(content, str) and content.strip():
            return content
        text = first.get(\"text\")
        if isinstance(text, str) and text.strip():
            return text

    # If nothing matched, return empty string to avoid surprises
    return \"\"


def _read_http_error(e: urllib.error.HTTPError) -> (str, Optional[dict]):
    try:
        raw = e.read().decode(\"utf-8\", errors=\"replace\")
        data = json.loads(raw)
        # OpenAI error envelope: {\"error\": {\"message\": ..., \"type\": ..., \"code\": ...}}
        if isinstance(data, dict) and \"error\" in data and isinstance(data[\"error\"], dict):
            err = data[\"error\"]
            msg = err.get(\"message\") or raw
            return str(msg), data
        # Responses API may embed structured error differently; fall back to raw
        return raw, data if isinstance(data, dict) else None
    except Exception:
        return str(e), None


# Minimal CLI for quick use: "'`python -m openai_client "prompt"`
def _main(argv: Optional[Iterable[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Stdlib-only OpenAI Responses client")
    parser.add_argument("prompt", nargs="?", help="Prompt text. If omitted or '"'-', read from stdin.\")
    parser.add_argument(\"--model\", default=os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"))
    parser.add_argument(\"--system\", default=None)
    parser.add_argument(\"--temperature\", type=float, default=None)
    parser.add_argument(\"--top-p\", dest=\"top_p\", type=float, default=None)
    parser.add_argument(\"--max-output-tokens\", dest=\"max_output_tokens\", type=int, default=None)
    parser.add_argument(\"--stream\", action=\"store_true\", help=\"Stream output as it arrives\")
    parser.add_argument(\"--base-url\", default=os.getenv(\"OPENAI_BASE_URL\", DEFAULT_BASE_URL))
    parser.add_argument(\"--organization\", default=os.getenv(\"OPENAI_ORG\"))
    parser.add_argument(\"--project\", default=os.getenv(\"OPENAI_PROJECT\"))
    parser.add_argument(\"--timeout\", type=float, default=float(os.getenv(\"OPENAI_TIMEOUT\", \"30\")))
    parser.add_argument(\"--api-key\", default=os.getenv(ENV_API_KEY))

    args = parser.parse_args(list(argv) if argv is not None else None)

    prompt_arg = args.prompt
    if not prompt_arg or prompt_arg == \"-\":
        prompt = sys.stdin.read()
    else:
        prompt = prompt_arg

    try:
        client = OpenAIClient(
            api_key=[REDACTED_SECRET]
            base_url=args.base_url,
            organization=args.organization,
            project=args.project,
            timeout=args.timeout,
            default_model=args.model,
        )
    except ValueError as e:
        print(str(e), file=sys.stderr)
        return 2

    try:
        if args.stream:
            for chunk in client.stream(
                prompt,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
                max_output_tokens=args.max_output_tokens,
            ):
                # Stream to stdout without extra buffering
                sys.stdout.write(chunk)
                sys.stdout.flush()
            print()
        else:
            text = client.complete(
                prompt,
                system=args.system,
                temperature=args.temperature,
                top_p=args.top_p,
                max_output_tokens=args.max_output_tokens,
            )
            print(text)
    except OpenAIAPIError as e:
        # Print a concise message to stderr; do not leak secrets
        detail = e.payload.get(\"error\", {}) if isinstance(e.payload, dict) else {}
        code = detail.get(\"code\") or \"\"
        print(f\"Error: {e.message} {f'({code})' if code else ''}\", file=sys.stderr)
        return 1

    return 0


if __name__ == \"__main__\":
    raise SystemExit(_main())
