        *,
        base_url: str = DEFAULT_BASE_URL,
        organization: Optional[str] = None,
        project: Optional[str] = None,
        timeout: float = 30.0,
        default_model: str = "gpt-4.1-mini",
    ) -> None:
        self.api_key = api_key or os.getenv(ENV_API_KEY) or ""
        if not self.api_key:
            raise ValueError(
                f"Missing API key. Set {ENV_API_KEY} or pass api_key explicitly."
            )
        self.base_url = base_url.rstrip("/")
        self.organization = organization or os.getenv("OPENAI_ORG")
        self.project = project or os.getenv("OPENAI_PROJECT")
        self.timeout = timeout
        self.default_model = default_model

    # Public API
    def respond(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        system: Optional[str] = None,
        temperature: Optional[float] = None,
        top_p: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        extra: Optional[Dict] = None,
    ) -> Dict:
        """Send a non-streaming Responses API call and return the JSON dict."""
        body: Dict[str, object] = {
            "model": model or self.default_model,
            "input": prompt,
        }
        if system is not None:
            body["system"] = system
        if temperature is not None:
            body["temperature"] = float(temperature)
        if top_p is not None:
            body["top_p"] = float(top_p)
        if max_output_tokens is not None:
            body["max_output_tokens"] = int(max_output_tokens)
        if extra:
            # last-wins merge for any advanced fields the caller wants to set
            body.update(extra)

        return self._json_request(RESPONSES_PATH, body, stream=False)

